// Line 195-215: Load from Redis ensures distributed consistency
private async loadFromRedis(): Promise<void> {
  try {
    const redisData = await this.redisClient.get(this.REDIS_KEY);

    if (redisData) {
      const parsedData = JSON.parse(redisData);
      this.config = {
        enabled: parsedData.enabled,
        cutoffDate: parsedData.cutoffDate 
          ? new Date(parsedData.cutoffDate) 
          : undefined,
        description: parsedData.description,
        enabledAt: parsedData.enabledAt 
          ? new Date(parsedData.enabledAt) 
          : undefined,
      };
    } else {
      // No config in Redis, ensure in-memory is disabled
      this.config = { enabled: false };
    }
  } catch (redisError) {
    this.logger.warn(`Failed to load from Redis, using in-memory:`, redisError);
    // Graceful fallback if Redis unavailable
  }
}
```

