  ${record.sync}, ${record.error}, ${record.warehouseJobId}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
)
ON CONFLICT ("deviceName", "inboxId") DO NOTHING    -- Line 126: Silently ignore duplicates
RETURNING *                                           -- Line 127: Return if inserted
```

**Conflict Resolution**:
- `ON CONFLICT`: Matches the primary key (deviceName, inboxId)
- `DO NOTHING`: Duplicates are rejected without error
- `RETURNING *`: Only returns the row if actually inserted (not if duplicate)

---

#### **2. Atomic Duplicate Detection** (lines 104-131)

```typescript
// Line 104-148: Individual upsert operations per record
const chunkInsertPromises = chunk.map(async (record) => {
  try {
    // Line 106-128: Raw SQL with ON CONFLICT DO NOTHING RETURNING
    const result = await this.prisma.$queryRaw<AndroidSyncInbox[]>`
      INSERT INTO "AndroidSyncInbox" (...)
      ON CONFLICT ("deviceName", "inboxId") DO NOTHING
      RETURNING *
    `;

    // Line 131: If RETURNING returns a record, it was actually inserted (not a duplicate)
    return result.length > 0 ? result[0] : null;
  } catch (error) {
    this.logger.error(...);
    return null;
