// Line 67-107: Extract lot number based on serial format
private extractLotNumberFromSerial(serialNumber: string): string | null {
  // First try dot-separated format
  const dotParts = serialNumber.split(".");

  if (dotParts.length >= 3) {
    // 3-part format: LOT.SUBLOT.BARREL → extract "LOT.SUBLOT"
    // Example: "25D23P.01.0278" → "25D23P.01" (canonical form)
    if (dotParts[0] && dotParts[1]) {
      return `${dotParts[0]}.${dotParts[1]}`;
    }
  } else if (dotParts.length === 2) {
    // 2-part format: LOT.BARREL → extract just "LOT"
    // Example: "25D23P.0001" → "25D23P" (variation form)
    if (dotParts[0]) {
      return dotParts[0];
    }
  }

  // ... [handle other formats]

  return null;
}
```

