buildUnifiedDirectWhere(
  filters: UnifiedBarrelFilterInput,
): Prisma.BarrelWhereInput {
  const where: Prisma.BarrelWhereInput = {};

  // Default filtering excludes removed barrels unless explicitly requested
  if (!filters.includeRemovedBarrels) {
    where.AND = [
      {
        OR: [
          { systemStatus: { not: EnumBarrelSystemStatus.PendingDeletion } },
          { systemStatus: null },
        ],
      },
      {
        OR: [
          {
            disposition: {
              notIn: [
                "Removed", "Dumped", "TransferredOffsite", "Rejected", "Orphaned"
              ],
            },
          },
          { disposition: null },
        ],
      },
    ];
  }

  // Apply all filter conditions
  // ... individual field handling

  return where;
}
```

