### 5. **Static File Serving** (`apps/whk-wms-front-end/app/api/docs/[...path]/route.ts:1-50`)

```typescript
export async function GET(
  _request: Request,
  { params }: { params: { path: string[] } }
) {
  // SECURITY: Prevent directory traversal
  for (const segment of params.path) {
    if (segment.includes('..') || segment.includes('/') || segment.includes('\\')) {
      return new NextResponse('Invalid path', { status: 400 })
    }
  }

  // SECURITY: Validate path stays within docs directory
  const filePath = path.join(process.cwd(), 'docs', ...params.path)
  const docsDir = path.join(process.cwd(), 'docs')
  const resolvedPath = path.resolve(filePath)

  if (!resolvedPath.startsWith(docsDir)) {
    return new NextResponse('Access denied', { status: 403 })
  }

  // SECURITY: Check file extension
  const extension = path.extname(filePath).toLowerCase()
  const ALLOWED_EXTENSIONS = ['.md', '.json', '.txt']
  if (!ALLOWED_EXTENSIONS.includes(extension)) {
    return new NextResponse('File type not allowed', { status: 403 })
  }

  // Read and return file with caching headers
  const fileContent = await fs.readFile(filePath, 'utf8')
  return new NextResponse(fileContent, {
    headers: {
      'Content-Type': contentType,
      'X-Content-Type-Options': 'nosniff',
      'Cache-Control': 'public, max-age=3600'
    }
  })
}
```

