## Answer to Question 32

**What is the purpose of bulk operation status tracking?**

Bulk operation status tracking provides **comprehensive feedback on partial success/failure scenarios**, allowing clients to understand which items succeeded, which failed, and why—while maintaining transaction safety and rollback capability.

### 1. **Status Response Structure** (`apps/whk-wms/src/bulk-barrel-operations/dto/bulk-operation-response.dto.ts:1-50`)

```typescript
@ObjectType()
export class BulkOperationError {
  @Field(() => String)
  barrelId!: string;

  @Field(() => String)
  message!: string;
}

@ObjectType()
export class BulkUpdateBarrelLocationsResponse {
  @Field(() => Boolean)
  success!: boolean;              // Overall operation success

  @Field(() => Number)
  updatedCount!: number;          // Count of successful updates

  @Field(() => [BulkOperationError], { nullable: true })
  errors?: BulkOperationError[];  // Per-item error details
}
```

**Three-part tracking**:
1. **success flag**: Indicates if ANY items were successfully processed
2. **updatedCount**: Quantifies successful operations
3. **errors array**: Per-item failure reasons (barrelId + message)

### 2. **Bulk Update Location Status Tracking** (`apps/whk-wms/src/bulk-barrel-operations/bulk-barrel-operations.service.ts:284-470`)

```typescript
async bulkUpdateBarrelLocations(
  updates: BarrelLocationUpdate[],
): Promise<BulkUpdateBarrelLocationsResponse> {
  const errors: BulkOperationError[] = [];
  let updatedCount = 0;

  // Pre-validation: Check for duplicate location assignments
  const locationCounts = new Map<string, number>();
  for (const update of updates) {
    const count = locationCounts.get(update.newLocationId) || 0;
    locationCounts.set(update.newLocationId, count + 1);
  }

  const duplicateLocations = Array.from(locationCounts.entries())
    .filter(([, count]) => count > 1)
    .map(([locationId]) => locationId);

  if (duplicateLocations.length > 0) {
    // Add errors for all updates targeting duplicate locations
    for (const update of updates) {
      if (duplicateLocations.includes(update.newLocationId)) {
        errors.push({
          barrelId: update.barrelId,
          message: `Cannot assign multiple barrels to the same location ${update.newLocationId}...`,
        });
      }
    }
  }

  // Filter out invalid updates
  const validUpdates = updates.filter(
    (update) => !duplicateLocations.includes(update.newLocationId),
  );

  try {
    await this.prisma.$transaction(async (prisma) => {
      // Per-item processing with individual error handling
      for (const update of validUpdates) {
        try {
          if (!existingBarrelIds.has(update.barrelId)) {
            errors.push({
              barrelId: update.barrelId,
              message: `Barrel with ID ${update.barrelId} not found`,
            });
            continue;  // Continue processing other items
          }

          if (!existingLocationIds.has(update.newLocationId)) {
            errors.push({
              barrelId: update.barrelId,
              message: `Storage location with ID ${update.newLocationId} not found`,
            });
            continue;
          }

          // Attempt update
          await prisma.barrel.update({
            where: { id: update.barrelId },
            data: { locationId: update.newLocationId },
          });

          updatedCount++;  // Increment on success
        } catch (error) {
          // Capture per-item error
          let errorMessage = "Unknown error";
          if (
            error.message.includes("Unique constraint failed") &&
            error.message.includes("locationId")
          ) {
            errorMessage = `Storage location with ID ${update.newLocationId} is already occupied`;
          }
          errors.push({
            barrelId: update.barrelId,
            message: errorMessage,
          });
        }
      }

      // Rollback if ALL items failed
      if (updatedCount === 0 && errors.length > 0) {
        throw new Error("All barrel location updates failed");
      }
    });

    // Return partial success response
    return {
      success: updatedCount > 0,
      updatedCount,
      errors: errors.length > 0 ? errors : undefined,
    };
  } catch (error) {
    throw new BadRequestException(`Bulk operation failed: ${errorMessage}`);
  }
}
```

**Key patterns**:
1. **Pre-validation phase**: Catch batch-level conflicts (duplicate locations) before transactions
2. **Per-item error handling**: Wrap each update in try-catch to isolate failures
3. **Incremental counting**: Increment `updatedCount` only on successful operations
4. **Transaction rollback**: If ALL items fail, throw error to rollback; if ANY succeed, commit
5. **Error collection**: Build array of `{barrelId, message}` for each failure

### 3. **Bulk Create Events Status Tracking** (`barrelEvent.service.ts:474-600`)

```typescript
async bulkCreateBarrelEvents(
  events: BarrelEventInput[],
): Promise<BulkCreateBarrelEventsResponse> {
  const errors: BulkOperationError[] = [];
  let createdCount = 0;

  try {
    await this.prisma.$transaction(async (prisma) => {
      // Pre-validate all resource IDs exist
      const existingBarrelsIds = new Set(
        (await prisma.barrel.findMany({ 
          where: { id: { in: barrelIds } },
          select: { id: true },
        })).map((b) => b.id)
      );

      const existingEventTypeIds = new Set(
        (await prisma.eventType.findMany({
          where: { id: { in: eventTypeIds } },
          select: { id: true },
        })).map((et) => et.id)
      );

      // Per-event processing
      for (const event of events) {
        try {
          if (!existingBarrelIds.has(event.barrelId)) {
            errors.push({
              barrelId: event.barrelId,
              message: `Barrel with ID ${event.barrelId} not found`,
            });
            continue;
          }

          if (!existingEventTypeIds.has(event.eventTypeId)) {
            errors.push({
              barrelId: event.barrelId,
              message: `Event type with ID ${event.eventTypeId} not found`,
            });
            continue;
          }

          // Create event
          await prisma.barrelEvent.create({
            data: {
              barrelId: event.barrelId,
              eventTypeId: event.eventTypeId,
              eventReasonId: event.eventReasonId || undefined,
              createdBy: event.createdBy,
              eventTime: event.eventTime || new Date(),
              notes: event.notes,
            },
          });

          createdCount++;
        } catch (error) {
          errors.push({
            barrelId: event.barrelId,
            message: error instanceof Error ? error.message : "Unknown error",
          });
        }
      }

      if (createdCount === 0 && errors.length > 0) {
        throw new Error("All barrel event creations failed");
      }
    });

    return {
      success: createdCount > 0,
      createdCount,
      errors: errors.length > 0 ? errors : undefined,
    };
  }
}
```

### 4. **Deprecation and REST Migration** (`bulk-barrel-operations.resolver.ts:57-75`)

```typescript
/**
 * @deprecated Use REST endpoint POST /api/barrels/bulk-operations instead
 * This GraphQL mutation is not transactional and will be removed in a future version.
 * The REST endpoint provides atomic operations with proper rollback support.
 * If barrel events fail to create, location updates are NOT rolled back.
 */
@Mutation(() => BulkUpdateBarrelLocationsResponse, {
  deprecationReason:
    "Use REST endpoint POST /api/barrels/bulk-operations instead. This mutation lacks transaction support.",
})
async bulkUpdateBarrelLocations(
  @Args() args: BulkUpdateBarrelLocationsArgs,
