### 4. **Summary Statistics** (`warehouse-jobs.service.ts:4655-4680`)

```typescript
// Calculate job summary (record count per job)
const jobSummaryMap = new Map<
  string,
  { jobId: string; jobTitle: string; jobColor: string; total: number; occupied: number; empty: number; status: string }
>();

recordsWithContext.forEach((record) => {
  if (!jobSummaryMap.has(record.jobId)) {
    const jobContext = jobColorMap.get(record.jobId);
    jobSummaryMap.set(record.jobId, {
      jobId: record.jobId,
      jobTitle: record.jobTitle,
      jobColor: record.jobColor,
      total: 0,
      occupied: 0,  // Staging context
      empty: 0,     // Staging context
