### Stage 1: Barrel Lookup with Normalization

**barrelEvent.service.ts:1909-2090** — `findOrCreateBarrel()` normalizes the serial by resolving lot variations:

```typescript
private async findOrCreateBarrel(
  tx: any,
  barrelSN: string,
  data: any,
  eventType: string,
  locationString?: string,
  skipNormalization?: boolean,
) {
  // Extract lot number from serial format
  // - 3+ parts: LOT.VARIATION.BARREL (e.g., '24H06A.99.0002') → lot = '24H06A.99'
  // - 2 parts: LOT.BARREL (e.g., '25G29AB.0007') → lot = '25G29AB'
  const snParts = barrelSN.split(".");
  const lotNumber = snParts.length >= 3 ? `${snParts[0]}.${snParts[1]}` : snParts[0];

  // Check if lot code is a variation and resolve to canonical lot
  const canonicalLot = await this.lotVariationService.findLotByNumberOrVariation(lotNumber);

  if (canonicalLot && canonicalLot.lotNumber !== lotNumber) {
    // Reconstruct serial with canonical lot
    const lotPartsUsed = snParts.length >= 3 ? 2 : 1;
    const remainingParts = snParts.slice(lotPartsUsed).join(".");
    normalizedSerial = `${canonicalLot.lotNumber}.${remainingParts}`;
  }

  // Try to find barrel with normalized serial
  let barrel = await tx.barrel.findFirst({
    where: {
      serialNumber: normalizedSerial,
      NOT: {
        OR: [
          { disposition: "Rejected" },
          { systemStatus: "PendingDeletion" },
        ],
      },
    },
  });

  if (!barrel) {
    // Barrel not found, call createBarrelByBruteforce
    barrel = await this.createBarrelByBruteforce(
      tx,
      normalizedSerial,
      data,
      eventType,
      locationString,
      skipNormalization,
    );
  }

  return barrel;
}
```

