    if (includeBarrels) {
      const inventory = await this.getInventoryAtDate(date, customerIdsArray);

      // Paginate barrel results within each period
      const paginatedBarrels = inventory.slice(
        (page - 1) * pageSize,
        page * pageSize,
      );

      snapshots.push({
        period: this.formatPeriod(date, period),
        periodStartDate: date,
        periodType: period,
        count: inventory.length,
        barrels: paginatedBarrels,
      });
    } else {
      // Optimized: just get counts
      const count = await this.getInventoryCountAtDate(date, customerIdsArray);
      snapshots.push({
        period: this.formatPeriod(date, period),
        periodStartDate: date,
        periodType: period,
        count: count,
      });
    }
  }

