### Partial Transfer Execution

**barrelOwnership.service.ts:395-480** — The `transferOwnership()` method handles partial transfers:

```typescript
async transferOwnership(
  barrelId: string,
  fromCustomerId: string,
  toCustomerId: string,
  userId: string,
  transferPercentage?: number,
  notes?: string,
  transferReasonId?: string,
  options?: {
    groupId?: string;
    operationId?: string;
    batchId?: string;
  },
) {
  // Step 1: Get current ownership
  const currentOwnership = await this.prisma.barrelOwnership.findFirst({
    where: {
      barrelId,
      customerId: fromCustomerId,
      validTo: null,  // Only active ownership
    },
  });

  if (!currentOwnership) {
    throw new BadRequestException(
      `No active ownership found for customer ${fromCustomerId} on barrel ${barrelId}`,
    );
  }

  // Step 2: Calculate transfer and remaining percentages
  const percentageToTransfer =
    transferPercentage || Number(currentOwnership.ownershipPercentage);
  const remainingPercentage =
    Number(currentOwnership.ownershipPercentage) - percentageToTransfer;

  return this.prisma.$transaction(async (tx) => {
    // Step 3: End current ownership (mark validTo as now)
    await tx.barrelOwnership.update({
      where: { id: currentOwnership.id },
      data: { validTo: new Date() },
    });

    const transfers = [];

    // Step 4: Create new ownership for recipient
    transfers.push(
      await tx.barrelOwnership.create({
        data: {
          barrelId,
          customerId: toCustomerId,
          ownershipType: EnumBarrelOwnershipType.SoleOwner,
          ownershipPercentage: percentageToTransfer,
          establishedBy: userId,
          validFrom: new Date(),
          notes: notes || `Transferred from customer ${fromCustomerId}`,
        },
      }),
    );

    // Step 5: Handle remaining ownership (if partial transfer)
    if (remainingPercentage > 0) {
      transfers.push(
        await tx.barrelOwnership.create({
          data: {
            barrelId,
            customerId: fromCustomerId,
            ownershipType: currentOwnership.ownershipType,  // Preserve type
            ownershipPercentage: remainingPercentage,
            jointOwnershipGroupId: currentOwnership.jointOwnershipGroupId,  // Preserve if joint
            inheritedFromCustomerId: currentOwnership.inheritedFromCustomerId,  // Preserve if inherited
            inheritanceDate: currentOwnership.inheritanceDate,  // Preserve inheritance date
            establishedBy: userId,
            validFrom: new Date(),
            notes: notes || `Remaining ownership after partial transfer`,
          },
        }),
      );
    }

    // Step 6: Record ownership transaction for audit trail
    await this.createOwnershipTransaction(
      EnumOwnershipTransactionType.TRANSFER,
      barrelId,
      userId,
      {
        fromCustomerId,
        toCustomerId,
        ownershipPercentage: percentageToTransfer,
        transferReasonId,
        notes,
        operationId: options?.operationId,
        batchId: options?.batchId,
        groupId: options?.groupId,
      },
      tx,
    );

    // Note: Deprecated barrel customer fields are automatically synced by DB trigger

    return transfers;
  });
}
```

### Transaction Recording

**barrelOwnership.service.ts:99-136** — The `createOwnershipTransaction()` method records the transfer:

```typescript
private async createOwnershipTransaction(
  transactionType: EnumOwnershipTransactionType,
  barrelId: string,
  executedBy: string,
  options: {
    fromCustomerId?: string;
    toCustomerId?: string;
    ownershipPercentage?: number;
    transferReasonId?: string;
    notes?: string;
    jointOwnershipGroupId?: string;
    operationId?: string;
    batchId?: string;
    groupId?: string;
  } = {},
  tx?: Prisma.TransactionClient,
) {
  const prismaClient = tx || this.prisma;

  const ownershipTransaction = await prismaClient.ownershipTransaction.create({
    data: {
      id: createId(),
      transactionType,
      barrelId,
      fromCustomerId: options.fromCustomerId,
      toCustomerId: options.toCustomerId,
      ownershipPercentage: options.ownershipPercentage ?? 100,  // Default to 100 if not specified
      transferReasonId: options.transferReasonId,
      notes: options.notes,
      executedBy,
      jointOwnershipGroupId: options.jointOwnershipGroupId,
      operationId: options.operationId,
      batchId: options.batchId,
      groupId: options.groupId,
    },
  });

  return ownershipTransaction;
}
```

