```typescript
private async handleExistingBarrelAtTarget(
  transactionClient: any,
  targetLocation: any,
  barrelSN: string,
  locationString: string,
  data: any,
  eventTypeName: string = "InventoryCheck",
): Promise<{ warningMessage: string; errorToLog: {...} | null; }> {
  if (!targetLocation) return { warningMessage: "", errorToLog: null };

  // CRITICAL: Check within transaction if location is already occupied
  const existingBarrelAtTarget = await transactionClient.barrel.findFirst({
    where: { locationId: targetLocation.id },
  });

  if (
    existingBarrelAtTarget &&
    existingBarrelAtTarget.serialNumber !== barrelSN
  ) {
    // AUTO-RESOLVE: Orphan the existing barrel (trust-but-log pattern)
    await transactionClient.barrel.update({
      where: { id: existingBarrelAtTarget.id },
      data: {
        locationId: null,
        holdingLocationId: null,
        disposition: "Orphaned",
      },
    });

    // Build error context for logging (deferred until after transaction)
    if (eventTypeName === "Relocation") {
      const errorToLog = {
        errorLevel: EnumDeviceSyncErrorLevel.WARN,
        errorType: "Relocation:LocationAlreadyOccupied",
        errorMessage: `Barrel ${existingBarrelAtTarget.serialNumber} already exists in ${locationString}. Relocating barrel ${barrelSN} to this location.`,
        context: {
          barrelSN: barrelSN,
          locationString: locationString,
          eventType: "Relocation",
          operator: data.operator,
          inboxDeviceName: data.inboxDeviceName || data.deviceName,
          existingBarrelSN: existingBarrelAtTarget.serialNumber,
          existingBarrelId: existingBarrelAtTarget.id,
        },
      };
      return { warningMessage: warningMsg, errorToLog };
    }
  }
  return { warningMessage: "", errorToLog: null };
}
