export async function authenticateUserRequest(request: NextRequest): Promise<AuthenticatedRequest | NextResponse> {
  try {
    // Extract user token from Authorization header
    const authHeader = request.headers.get('authorization')
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return NextResponse.json(
        { message: 'Authorization header with Bearer token is required' },
        { status: 401 }
      )
    }

    const token = authHeader.slice(7).trim() // Remove 'Bearer ' prefix
    if (!token) {
      return NextResponse.json(
        { message: 'Valid Bearer token is required' },
        { status: 401 }
      )
    }

    // Parse and validate JSON body for requests that expect a body
    let body: any = null
    if (['POST', 'PUT', 'PATCH'].includes(method)) {
      try {
        body = await request.json()
      } catch (parseError) {
        return NextResponse.json(
          { message: 'Invalid JSON in request body' },
          { status: 400 }
        )
      }
    }

    // Decode user claims from JWT token
    const user = decodeJwtClaims(token)
    if (!user) {
      console.warn('Failed to decode user claims from token')
    }

    return { token, body, user }
