### JWT Claim Decoding (api-security.ts:82-139)

**api-security.ts:82-139** - Extracts and validates token claims without signature verification:

```typescript
function decodeJwtClaims(token: string): UserClaims | null {
  try {
    // JWT tokens have 3 parts separated by dots: header.payload.signature
    const parts = token.split('.')
    if (parts.length !== 3) {
      console.warn('Invalid JWT format: expected 3 parts')
      return null
    }

    // Decode the payload (second part)
    const payload = parts[1]
    // Replace URL-safe characters and add padding if needed
    const normalizedPayload = payload.replace(/-/g, '+').replace(/_/g, '/')
    const paddedPayload = normalizedPayload + '='.repeat((4 - normalizedPayload.length % 4) % 4)

    // Decode base64 (using Buffer as fallback for Node.js environments)
    let decodedPayload: string
    try {
      decodedPayload = typeof atob !== 'undefined' 
        ? atob(paddedPayload)
        : Buffer.from(paddedPayload, 'base64').toString('utf-8')
    } catch (decodeError) {
      console.warn('Failed to decode JWT payload:', decodeError)
      return null
    }

    const claims = JSON.parse(decodedPayload) as UserClaims

    // Basic validation - ensure we have at least a subject (user ID)
    if (!claims.sub && !claims.oid) {
      console.warn('JWT claims missing required subject or object ID')
      return null
    }

    return claims
```

This decodes the JWT payload to extract claims like `sub` (subject/user ID), `oid` (Azure AD Object ID), `name`, `email`, `roles`, etc.

