private determineSessionStatus(
  successRows: number,
  errorRows: number,
  processedRows: number,
  totalRows: number,
): EnumInventoryUploadStatus | null {
  // Don't change status if processing is not complete
  if (processedRows < totalRows) {
    return null; // Keep current status
