function useProgress() {
  const [state, setState] = useState<
    'initial' | 'in-progress' | 'completing' | 'complete'
  >('initial');

  const value = useSpring(0, {
    damping: 25,
    mass: 0.5,
    stiffness: 300,
    restDelta: 0.1
  });

  useInterval(
    () => {
      if (value.get() === 100) {
        value.jump(0);
      }

      const current = value.get();
      let diff;
      if (current === 0) {
        diff = 15;        // Initial jump: 15%
      } else if (current < 50) {
        diff = rand(1, 10); // Early stage: 1-10%
      } else {
        diff = rand(1, 5);  // Late stage: 1-5%
      }

      value.set(Math.min(current + diff, 99));
    },
    state === 'in-progress' ? 750 : null
  );

  return { state, value, start, done, reset };
}
