**updateRateHistory()** (progress-tracking.service.ts:200-240):
```typescript
private updateRateHistory(
  sessionId: string,
  currentProcessedRows: number,
  timestamp: Date,
): number {
  const history = this.rateHistory.get(sessionId) || [];
  let instantaneousRate = 0;

  // Calculate instantaneous rate if we have previous data
  if (history.length > 0) {
    const lastSnapshot = history[history.length - 1];
    const timeDiffSeconds =
      (timestamp.getTime() - lastSnapshot.timestamp.getTime()) / 1000;
    const rowsDiff = currentProcessedRows - lastSnapshot.processedRows;

    if (timeDiffSeconds > 0) {
      instantaneousRate = rowsDiff / timeDiffSeconds;
      // Cap extremely high rates that might be outliers
      instantaneousRate = Math.min(
        instantaneousRate,
        lastSnapshot.instantaneousRate * 3,
      );
    }
  }

  const newSnapshot: RateSnapshot = {
    timestamp,
    processedRows: currentProcessedRows,
    instantaneousRate: Math.max(0, instantaneousRate),
  };

  history.push(newSnapshot);

  // Maintain history size limit
  if (history.length > this.smoothingConfig.maxHistorySize) {
    history.shift();
  }

  this.rateHistory.set(sessionId, history);
  return instantaneousRate;
}
```

**Smoothing Strategy** (progress-tracking.service.ts:242-267):
```typescript
private calculateSmoothedRate(sessionId: string): number {
  const history = this.rateHistory.get(sessionId) || [];

  if (history.length < this.smoothingConfig.minSamplesForEstimate) {
    return 0;
  }

  // Calculate Simple Moving Average
  const smaRate = this.calculateSimpleMovingAverage(history);

  // Calculate Exponential Moving Average
  const emaRate = this.calculateExponentialMovingAverage(sessionId, history);

  // For early stages, prefer SMA for stability; later prefer EMA for responsiveness
  if (history.length < this.smoothingConfig.smaWindowSize) {
    return smaRate;  // ← Early: stable moving average
  }

  // Use EMA for more responsive estimates once we have enough data
  return emaRate;   // ← Later: responsive EMA
}
```

