### 6. **Time Estimation with Confidence**

**progress-tracking.service.ts:182-227** calculates remaining time with confidence levels:

```typescript
async calculateEstimatedTimeRemaining(
  sessionId: string,
): Promise<TimeEstimate> {
  const progress = await this.getSessionProgress(sessionId);
  const processingRate = await this.calculateProcessingRate(sessionId);

  const remainingRows = progress.totalRows - progress.processedRows;

  if (remainingRows <= 0) {
    return {
      estimatedCompletionTime: progress.processingCompletedAt || new Date(),
      remainingTimeSeconds: 0,
      remainingTimeFormatted: "0 seconds",
      processingRate,
      confidence: "high",
    };
  }

  // Use smoothed rate for estimation if available, otherwise fall back to overall rate
  const rateForEstimation =
    processingRate.smoothedRate && processingRate.smoothedRate > 0
      ? processingRate.smoothedRate
      : processingRate.rowsPerSecond;

  if (rateForEstimation <= 0) {
    return { processingRate, confidence: "low" };
  }

  const remainingTimeSeconds = remainingRows / rateForEstimation;
  const estimatedCompletionTime = new Date(
    Date.now() + remainingTimeSeconds * 1000,
  );

  const confidence = this.calculateConfidence(sessionId);

  return {
    estimatedCompletionTime,
    remainingTimeSeconds: parseFloat(remainingTimeSeconds.toFixed(2)),
    remainingTimeFormatted: this.formatDuration(remainingTimeSeconds),
    processingRate,
    confidence,
  };
}
```

**calculateConfidence()** (progress-tracking.service.ts:289-320) evaluates rate stability:
```typescript
private calculateConfidence(sessionId: string): "low" | "medium" | "high" {
  const history = this.rateHistory.get(sessionId) || [];

  if (history.length < this.smoothingConfig.minSamplesForEstimate) {
    return "low";  // ← Not enough data
  }

  if (history.length < this.smoothingConfig.smaWindowSize) {
    return "medium";  // ← Still warming up
  }

  // Calculate rate variance to determine stability
  const recentRates = history
    .slice(-this.smoothingConfig.smaWindowSize)
    .map((snapshot) => snapshot.instantaneousRate)
    .filter((rate) => rate > 0);

  if (recentRates.length < 3) {
    return "medium";
  }

  const mean =
    recentRates.reduce((sum, rate) => sum + rate, 0) / recentRates.length;
  const variance =
    recentRates.reduce((sum, rate) => sum + Math.pow(rate - mean, 2), 0) /
    recentRates.length;
  const coefficientOfVariation = Math.sqrt(variance) / mean;

  // Lower coefficient of variation indicates more stable rates
  if (coefficientOfVariation < 0.2) {
    return "high";    // ← Very stable
  } else if (coefficientOfVariation < 0.5) {
    return "medium";  // ← Moderately stable
  } else {
    return "low";     // ← Highly variable
  }
}
```

