function getRepdbRequestLogFields(req: RequestWithRepdbMetadata): Record<string, unknown> {
  const fields: Record<string, unknown> = {};
  const meta = req?.whkOperationMetadata;

  if (typeof req?.whkCorrelationId === "string" && req.whkCorrelationId.length > 0) {
    fields.correlationId = req.whkCorrelationId;  // Trace request across services
  }

  if (typeof meta.origin === "string") {
    fields.origin = meta.origin;  // Which system triggered the operation
  }

  if (typeof meta.readConsistency === "string") {
    fields.read_consistency = meta.readConsistency;  // PRIMARY or REPLICA
  }

  if (meta.dbFallback === 0 || meta.dbFallback === 1) {
    fields.db_fallback = meta.dbFallback;  // Did we fallback to primary DB?
  }

  if (typeof meta.dbTargetChosen === "string") {
    fields.db_target = meta.dbTargetChosen;  // Which database instance?
  }

  return fields;
}
