while (iterations < maxIterations) {
  iterations++;

  // Check timeout
  if (Date.now() - startTime > timeout) {
    return { response: "Request timed out", ... };
  }

  // Call Claude with available tools
  const response = await this.anthropicService.createMessageWithTools(
    messages,
    tools,
    { systemPrompt: DEFAULT_SYSTEM_PROMPT },
  );

  // If Claude finishes (end_turn), extract response and return
  if (response.stop_reason === "end_turn") {
    const finalResponse = this.anthropicService.extractTextContent(response);
    return { response: finalResponse, toolsUsed, toolExecutions, iterations, ... };
  }

  // If Claude wants tools (tool_use), execute them
  if (response.stop_reason === "tool_use") {
    const toolUses = this.anthropicService.extractToolUses(response);

    // Add Claude's response to message history
    messages.push({ role: "assistant", content: response.content });

    // Execute each tool and collect results
    const toolResults: ClaudeContentBlock[] = [];
    for (const toolUse of toolUses) {
      const result = await this.mcpService.executeTool(
        toolUse.name,
        toolUse.input as Record<string, unknown>,
        context,
      );
      toolResults.push(
        this.anthropicService.buildToolResultBlock(toolUse.id, resultText, result.isError),
      );
    }

    // Add tool results to messages for next iteration
    messages.push({ role: "user", content: toolResults });
  }
}
```

