### WebSocket Singleton Socket Management (useAgentSocket.ts:142-195)

```typescript
// Module-level singleton socket manager to avoid React lifecycle issues
let socketInstance: SocketInstance | null = null;

function getOrCreateSocket(token: string, url: string): Socket {
  // If we have an existing socket with same token/url, reuse it
  if (socketInstance &&
      socketInstance.token === token &&
      socketInstance.url === url) {
    // Check if socket is disconnected and reconnect if needed
    if (!socketInstance.socket.connected) {
      console.log('🔌 Agent socket: Socket disconnected, reconnecting');
      socketInstance.socket.connect();
    }
    socketInstance.refCount++;
    console.log('🔌 Agent socket: Reusing existing socket, refCount:', socketInstance.refCount);
    return socketInstance.socket;
  }

  // Different config or no socket - disconnect old one if exists
  if (socketInstance) {
    console.log('🔌 Agent socket: Config changed, disconnecting old socket');
    socketInstance.socket.disconnect();
    socketInstance = null;
  }

  console.log('🔌 Agent socket: Creating new singleton socket to', url);

  const socket = io(`${url}/agent`, {
    auth: { token },
    transports: ['websocket', 'polling'],
    reconnection: true,
    reconnectionAttempts: 5,
    reconnectionDelay: 1000,
    reconnectionDelayMax: 5000,
    forceNew: false,
    autoConnect: true,
  });

  socketInstance = {
    socket,
    token,
    url,
    refCount: 1,
  };

  return socket;
}
```

The singleton pattern with **reference counting** prevents multiple Socket.IO instances—critical for avoiding duplicate connections when multiple components (floating button + full-page chat) use the agent simultaneously.

